package engine

// The number data of Intl.NumberFormat and Intl.PluralRules
// (intl_number_tables.go, generated by internal/gen/cldr): a data locale's
// symbols and patterns decode on the first use of the locale, behind a
// sync.Once per data index; a formatter finds its currency names and unit
// patterns in their tables when it is constructed; a plural rule set
// compiles on its first use, behind a sync.Once each. Every string decoded
// is a substring of the tables' constants, or of a regional locale's
// records, which are built once per process (intlLocaleTable).

import (
	"strings"
	"sync"
)

// Indexes of intlNumSystem.sym, in the order of the tables' fields.
const (
	intlSymDecimal = iota
	intlSymGroup
	intlSymPercent
	intlSymPlus
	intlSymMinus
	intlSymApprox
	intlSymExponential
	intlSymInfinity
	intlSymNaN
	intlSymCurrencyDecimal // the separators of currency amounts
	intlSymCurrencyGroup
	intlSymCount
)

// intlNumSystem is a numbering system's data in a locale.
type intlNumSystem struct {
	nu  string
	sym [intlSymCount]string
	// The decimal, percent, scientific, currency and accounting patterns.
	decimal, percent, scientific, currency, accounting string
	// spacing is the currency spacing before the currency (currencyMatch,
	// surroundingMatch, insertBetween), then after it.
	spacing      [6]string
	rangePattern string
	// The compact tables of the short and long decimal and the short
	// currency formats ("" for none: ICU falls back from long to short).
	compactShort, compactLong, compactCurrency string
}

// intlNumLocale is a data locale's number data.
type intlNumLocale struct {
	index       int
	minGrouping int
	// currencyUnit holds the currency long name patterns ("{0} {1}") by
	// plural category.
	currencyUnit [6]string
	// overrides lists the currencies with a pattern and separators of their
	// own.
	overrides string
	systems   []intlNumSystem // latn first
	cardinal  *intlPluralRuleSet
	cats      []intlPluralCategory // the cardinal categories, other included
	// currencyAt holds the offset of each entry of the locale's currency
	// names, built on the first currency formatter of the locale.
	currencyOnce sync.Once
	currencyAt   []uint32
}

var intlNumLocales [intlDataIndexCount]struct {
	once sync.Once
	l    *intlNumLocale
}

// intlNumLocaleAt returns the number data of a data index, decoding it on
// first use.
func intlNumLocaleAt(i int) *intlNumLocale {
	e := &intlNumLocales[i]
	e.once.Do(func() { e.l = decodeIntlNumLocale(i) })
	return e.l
}

func decodeIntlNumLocale(i int) *intlNumLocale {
	recs := strings.Split(intlNumberTable.record(i), "\x1e")
	l := &intlNumLocale{index: i}
	lf := strings.Split(recs[0], "\x1f")
	l.minGrouping = int(lf[0][0] - '0')
	intlEachCoded(lf[1], func(c byte, v string) { l.currencyUnit[intlPluralCode(c)] = v })
	l.overrides = lf[2]
	l.systems = make([]intlNumSystem, len(recs)-1)
	for k, rec := range recs[1:] {
		f := strings.Split(rec, "\x1f")
		if k > 0 {
			// An empty field is latn's.
			latn := intlSystemFields(&l.systems[0])
			for j := 1; j < len(f); j++ {
				if f[j] == "" {
					f[j] = latn[j-1]
				}
			}
		}
		s := &l.systems[k]
		s.nu = f[0]
		copy(s.sym[:], f[1:1+intlSymCount])
		p := f[1+intlSymCount:]
		s.decimal, s.percent, s.scientific, s.currency, s.accounting = p[0], p[1], p[2], p[3], p[4]
		copy(s.spacing[:], p[5:11])
		s.rangePattern = p[11]
		s.compactShort, s.compactLong, s.compactCurrency = p[12], p[13], p[14]
	}
	l.cardinal = intlPluralRules(intlDataLocale(i), false)
	l.cats = l.cardinal.categories()
	return l
}

// intlSystemFields returns a system's fields in the tables' order, its id
// excluded.
func intlSystemFields(s *intlNumSystem) []string {
	f := make([]string, 0, intlSymCount+15)
	f = append(f, s.sym[:]...)
	f = append(f, s.decimal, s.percent, s.scientific, s.currency, s.accounting)
	f = append(f, s.spacing[:]...)
	return append(f, s.rangePattern, s.compactShort, s.compactLong, s.compactCurrency)
}

// intlNuValues caches intlNumberingValues by available locale with data.
var intlNuValues sync.Map

// intlNumberingValuesOf is intlNumberingValues of an available locale with
// data, built once per locale.
func intlNumberingValuesOf(dataLocale string) []string {
	if v, ok := intlNuValues.Load(dataLocale); ok {
		return v.([]string)
	}
	v := intlNumberingValues(dataLocale)
	if intlHasData(dataLocale) {
		intlNuValues.Store(dataLocale, v)
	}
	return v
}

// system returns the data of a numbering system, latn's when the locale has
// none of its own (its digits apart, which the formatter maps).
func (l *intlNumLocale) system(nu string) *intlNumSystem {
	for k := range l.systems {
		if l.systems[k].nu == nu {
			return &l.systems[k]
		}
	}
	return &l.systems[0]
}

// intlEachCoded calls fn with each "<code><text>" item of a 0x1D-separated
// list.
func intlEachCoded(s string, fn func(code byte, v string)) {
	for s != "" {
		end := strings.IndexByte(s, 0x1d)
		if end < 0 {
			end = len(s)
		}
		fn(s[0], s[1:end])
		s = s[min(end+1, len(s)):]
	}
}

// intlPluralCode returns the category of a code of the tables.
func intlPluralCode(c byte) intlPluralCategory {
	return intlPluralCategory(strings.IndexByte("zotfmx", c))
}

// currencyOverride returns the pattern and separators of a currency that has
// its own in the locale, else those of the locale's default currency ("*"),
// which ICU keeps for a currency without its own.
func (l *intlNumLocale) currencyOverride(code string) (pattern, decimal, group string, ok bool) {
	for s := l.overrides; s != ""; {
		end := strings.IndexByte(s, 0x1c)
		if end < 0 {
			end = len(s)
		}
		f := strings.Split(s[:end], "\x1d")
		if f[0] == code {
			return f[1], f[2], f[3], true
		}
		if f[0] == "*" {
			pattern, decimal, group, ok = f[1], f[2], f[3], true
		}
		s = s[min(end+1, len(s)):]
	}
	return pattern, decimal, group, ok
}

// intlCurrencyInfo is a currency's symbols and names in a locale.
type intlCurrencyInfo struct {
	symbol, narrow string
	names          [6]string // by plural category
}

// intlListIndex returns the index of a code in a list of three-letter
// codes, -1 when absent.
func intlListIndex(list, code string) int {
	lo, hi := 0, len(list)/3
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch c := list[3*m : 3*m+3]; {
		case c == code:
			return m
		case c < code:
			lo = m + 1
		default:
			hi = m
		}
	}
	return -1
}

// intlNthRecord returns the n-th record of a 0x1E-separated list.
func intlNthRecord(s string, n int) string {
	for range n {
		s = s[strings.IndexByte(s, 0x1e)+1:]
	}
	if end := strings.IndexByte(s, 0x1e); end >= 0 {
		return s[:end]
	}
	return s
}

// currencyNames returns a currency's symbols and plural names in the
// locale: the code where CLDR has none.
func (l *intlNumLocale) currencyNames(code string) intlCurrencyInfo {
	n := intlCurrencyInfo{symbol: code}
	k := intlListIndex(intlCurrencyList, code)
	var f [8]string
	if k >= 0 {
		l.currencyOnce.Do(func() {
			s := intlCurrencyTable.record(l.index)
			at := make([]uint32, 0, len(intlCurrencyList)/3+1)
			at = append(at, 0)
			for i := 0; i < len(s); i++ {
				if s[i] == 0x1e {
					at = append(at, uint32(i+1))
				}
			}
			l.currencyAt = append(at, uint32(len(s)+1))
		})
		rec := intlCurrencyTable.record(l.index)[l.currencyAt[k] : l.currencyAt[k+1]-1]
		for i := 0; rec != "" && i < len(f); i++ {
			end := strings.IndexByte(rec, 0x1f)
			if end < 0 {
				end = len(rec)
			}
			f[i] = rec[:end]
			rec = rec[min(end+1, len(rec)):]
		}
	}
	if f[0] != "" {
		n.symbol = f[0]
	}
	n.narrow = n.symbol
	if f[1] != "" {
		n.narrow = f[1]
	}
	other := code
	if f[2] != "" {
		other = f[2]
	}
	j := 3
	for _, c := range l.cats {
		if c == intlPluralOther {
			continue
		}
		n.names[c] = other
		if f[j] != "" {
			n.names[c] = f[j]
		}
		j++
	}
	n.names[intlPluralOther] = other
	return n
}

// intlCurrencyDigitsOf implements CurrencyDigits (ECMA-402 §16.5.1):
// currencyData's digits, 2 for a currency it does not list.
func intlCurrencyDigitsOf(code string) int {
	s := intlCurrencyDigits
	lo, hi := 0, len(s)/4
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		switch c := s[4*m : 4*m+3]; {
		case c == code:
			return int(s[4*m+3] - '0')
		case c < code:
			lo = m + 1
		default:
			hi = m
		}
	}
	return 2
}

// intlCurrencyCodes returns the currencies in use, sorted: those the
// currency option has data for (Intl.supportedValuesOf("currency")).
func intlCurrencyCodes() []string {
	list := make([]string, len(intlCurrencyCurrent)/3)
	for i := range list {
		list[i] = intlCurrencyCurrent[3*i : 3*i+3]
	}
	return list
}

// intlSimpleUnits returns the sanctioned single units, sorted
// (Intl.supportedValuesOf("unit")).
func intlSimpleUnits() []string {
	return strings.Split(intlUnitList, ",")[:intlSanctionedUnitCount]
}

// intlUnitIndex returns the index of a unit in intlUnitList, -1 when the
// list does not have it.
func intlUnitIndex(unit string) int {
	s := intlUnitList
	for i := 0; s != ""; i++ {
		end := strings.IndexByte(s, ',')
		if end < 0 {
			end = len(s)
		}
		if s[:end] == unit {
			return i
		}
		s = s[min(end+1, len(s)):]
	}
	return -1
}

// intlIsSanctionedUnit implements IsSanctionedSingleUnitIdentifier
// (ECMA-402 §6.6.2).
func intlIsSanctionedUnit(unit string) bool {
	i := intlUnitIndex(unit)
	return i >= 0 && i < intlSanctionedUnitCount
}

// Unit widths, in the order of intlUnitData's forms.
const (
	intlUnitLong = iota
	intlUnitShort
	intlUnitNarrow
)

// intlUnitForm is a unit's patterns in a width.
type intlUnitForm struct {
	patterns [6]string // "{0} km" by plural category
	per      string    // the per form, "{0}/km" ("" for a built-in per unit)
}

// unitForm returns the patterns of the unit of index k in a width.
func (l *intlNumLocale) unitForm(k, width int) intlUnitForm {
	rec := intlNthRecord(intlUnitTable.record(l.index), k)
	forms := strings.SplitN(rec, "\x1d", 3)
	form := forms[width]
	if width == intlUnitNarrow && form == "" {
		form = forms[intlUnitShort]
	}
	f := strings.Split(form, "\x1f")
	var u intlUnitForm
	other := f[0]
	j := 1
	for _, c := range l.cats {
		if c == intlPluralOther {
			continue
		}
		u.patterns[c] = other
		if f[j] != "" {
			u.patterns[c] = f[j]
		}
		j++
	}
	u.patterns[intlPluralOther] = other
	if k < intlSanctionedUnitCount {
		u.per = f[j]
	}
	return u
}

var intlPluralSets [intlPluralRuleSetCount]struct {
	once sync.Once
	s    *intlPluralRuleSet
}

// intlPluralSet returns the rule set of an index of intlPluralRuleSets,
// compiling it on first use.
func intlPluralSet(i int) *intlPluralRuleSet {
	e := &intlPluralSets[i]
	e.once.Do(func() {
		s := intlPluralRuleSets
		for range i {
			s = s[strings.IndexByte(s, '\n')+1:]
		}
		if end := strings.IndexByte(s, '\n'); end >= 0 {
			s = s[:end]
		}
		e.s = parseIntlPluralRules(s)
	})
	return e.s
}

// intlPluralRecord returns the field of a locale's record in
// intlPluralLocales (0 cardinal, 1 ordinal, 2 ranges), truncating the tag
// until a record has it, -1 when none does.
func intlPluralRecord(tag string, field int) int {
	prefix := intlRemoveUnicodeExtension(tag)
	for prefix != "" {
		if v, ok := intlRecord(intlPluralLocales, prefix); ok {
			for range field {
				v = v[strings.IndexByte(v, ',')+1:]
			}
			if end := strings.IndexByte(v, ','); end >= 0 {
				v = v[:end]
			}
			if v != "" {
				n := 0
				for i := 0; i < len(v); i++ {
					n = n*10 + int(v[i]-'0')
				}
				return n
			}
		}
		pos := max(strings.LastIndexByte(prefix, '-'), 0)
		for pos >= 2 && prefix[pos-2] == '-' {
			pos -= 2
		}
		prefix = prefix[:pos]
	}
	return -1
}

// intlPluralRules returns the cardinal or ordinal rules of a locale: those
// of its tag truncated until CLDR has rules for it, else root's.
func intlPluralRules(tag string, ordinal bool) *intlPluralRuleSet {
	field := 0
	if ordinal {
		field = 1
	}
	i := intlPluralRecord(tag, field)
	if i < 0 {
		i = intlPluralRecord("root", field)
	}
	if i < 0 {
		i = 0 // the empty rule set: other
	}
	return intlPluralSet(i)
}

// intlPluralRangesOf returns the plural range triples of a locale's
// language ("" when CLDR has none).
func intlPluralRangesOf(tag string) string {
	lang := tag
	if i := strings.IndexByte(tag, '-'); i >= 0 {
		lang = tag[:i]
	}
	v, ok := intlRecord(intlPluralLocales, lang)
	if !ok {
		return ""
	}
	v = v[strings.LastIndexByte(v, ',')+1:]
	if v == "" {
		return ""
	}
	n := 0
	for i := 0; i < len(v); i++ {
		n = n*10 + int(v[i]-'0')
	}
	s := intlPluralRanges
	for range n {
		s = s[strings.IndexByte(s, '\n')+1:]
	}
	if end := strings.IndexByte(s, '\n'); end >= 0 {
		s = s[:end]
	}
	return s
}

// intlPluralRange resolves the category of a range from its start's and
// end's (ICU's StandardPluralRanges::resolve): the triple's result, other
// when there is none.
func intlPluralRange(triples string, start, end intlPluralCategory) intlPluralCategory {
	const codes = "zotfmx"
	for i := 0; i+3 <= len(triples); i += 3 {
		if triples[i] == codes[start] && triples[i+1] == codes[end] {
			return intlPluralCode(triples[i+2])
		}
	}
	return intlPluralOther
}
